import{_ as e,o as d,c as o,a6 as n}from"./chunks/framework.BBdhcoHf.js";const m=JSON.parse('{"title":"Control Codes","description":"","frontmatter":{},"headers":[],"relativePath":"protocols/sbrp/control-codes.md","filePath":"protocols/sbrp/control-codes.md","lastUpdated":1772116603000}'),a={name:"protocols/sbrp/control-codes.md"};function r(i,t,s,c,l,h){return d(),o("div",null,[...t[0]||(t[0]=[n('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /protocols/sbrp/control-codes.md for this page in Markdown format</div><h1 id="control-codes" tabindex="-1">Control Codes <a class="header-anchor" href="#control-codes" aria-label="Permalink to “Control Codes”">​</a></h1><blockquote><p><strong>Authority</strong>: Primary (Reference)<br><strong>Purpose</strong>: Catalog of control code values, names, and flags. Behavioral semantics defined in <a href="./state-machine">state-machine.md</a>.<br><strong>Stability Note</strong>: This document exists to stabilize numeric code assignments. Once the control code set is frozen, this catalog MAY be inlined into state-machine.md as an appendix.</p></blockquote><h2 id="code-ranges" tabindex="-1">Code Ranges <a class="header-anchor" href="#code-ranges" aria-label="Permalink to “Code Ranges”">​</a></h2><p>Control frames (<code>0x20</code>) are relay-originated only. Ranges enable category discrimination:</p><table tabindex="0"><thead><tr><th>Range</th><th>Category</th><th>Description</th></tr></thead><tbody><tr><td><code>0x01xx</code></td><td>Authentication</td><td>Token and authorization errors</td></tr><tr><td><code>0x02xx</code></td><td>Routing</td><td>Daemon discovery and presence</td></tr><tr><td><code>0x03xx</code></td><td>Session</td><td>Session lifecycle errors</td></tr><tr><td><code>0x04xx</code></td><td>Wire format</td><td>Protocol violations</td></tr><tr><td><code>0x05xx</code></td><td>Reserved</td><td>Future use</td></tr><tr><td><code>0x06xx</code></td><td>Internal</td><td>Relay internal errors</td></tr><tr><td><code>0x07xx–0x08xx</code></td><td>Reserved</td><td>Future use</td></tr><tr><td><code>0x09xx</code></td><td>Throttling</td><td>Traffic control (varies: N/T)</td></tr><tr><td><code>0x0Axx–0x0Fxx</code></td><td>Reserved</td><td>Future use</td></tr><tr><td><code>0x10xx</code></td><td>Session state</td><td>Non-terminal state transitions</td></tr><tr><td><code>0x11xx–0x1Fxx</code></td><td>Reserved</td><td>Future state notifications</td></tr><tr><td><code>0xE0xx</code></td><td>SDK-only</td><td>Never transmitted on wire</td></tr></tbody></table><h2 id="wire-codes-relay-→-endpoint" tabindex="-1">Wire Codes (Relay → Endpoint) <a class="header-anchor" href="#wire-codes-relay-→-endpoint" aria-label="Permalink to “Wire Codes (Relay → Endpoint)”">​</a></h2><p><strong>Legend</strong>: T=terminal (closes WebSocket), N=non-terminal. SID: 0=connection-level, S=session-specific.</p><h3 id="authentication-0x01xx" tabindex="-1">Authentication (0x01xx) <a class="header-anchor" href="#authentication-0x01xx" aria-label="Permalink to “Authentication (0x01xx)”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Name</th><th>T/N</th><th>SID</th><th>Meaning</th><th>When Emitted</th></tr></thead><tbody><tr><td>0x0101</td><td><code>unauthorized</code></td><td>T</td><td>0</td><td>Invalid or expired token</td><td>Token validation failure</td></tr><tr><td>0x0102</td><td><code>forbidden</code></td><td>T</td><td>0</td><td>Valid token, access denied</td><td>User doesn&#39;t own daemon</td></tr></tbody></table><h3 id="routing-0x02xx" tabindex="-1">Routing (0x02xx) <a class="header-anchor" href="#routing-0x02xx" aria-label="Permalink to “Routing (0x02xx)”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Name</th><th>T/N</th><th>SID</th><th>Meaning</th><th>When Emitted</th></tr></thead><tbody><tr><td>0x0201</td><td><code>daemon_not_found</code></td><td>T</td><td>S</td><td>Unknown daemon ID</td><td>Daemon doesn&#39;t exist</td></tr><tr><td>0x0202</td><td><code>daemon_offline</code></td><td>T</td><td>S</td><td>Daemon not connected</td><td>Client connects, daemon offline</td></tr></tbody></table><h3 id="session-0x03xx" tabindex="-1">Session (0x03xx) <a class="header-anchor" href="#session-0x03xx" aria-label="Permalink to “Session (0x03xx)”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Name</th><th>T/N</th><th>SID</th><th>Meaning</th><th>When Emitted</th></tr></thead><tbody><tr><td>0x0301</td><td><code>session_not_found</code></td><td>T</td><td>S</td><td>Unknown session ID</td><td>Frame references invalid session</td></tr><tr><td>0x0302</td><td><code>session_expired</code></td><td>T</td><td>S</td><td>Session terminated</td><td>Grace expired, Signal(close), or policy</td></tr></tbody></table><h3 id="wire-format-0x04xx" tabindex="-1">Wire Format (0x04xx) <a class="header-anchor" href="#wire-format-0x04xx" aria-label="Permalink to “Wire Format (0x04xx)”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Name</th><th>T/N</th><th>SID</th><th>Meaning</th><th>When Emitted</th></tr></thead><tbody><tr><td>0x0401</td><td><code>malformed_frame</code></td><td>T</td><td>0</td><td>Invalid header structure</td><td>Header parse failure, truncated frame</td></tr><tr><td>0x0402</td><td><code>payload_too_large</code></td><td>T</td><td>0</td><td>Exceeds 64KB limit</td><td>Payload length &gt; MAX_PAYLOAD_SIZE</td></tr><tr><td>0x0403</td><td><code>invalid_frame_type</code></td><td>T</td><td>0</td><td>Unknown type byte</td><td>Type byte not in defined set</td></tr><tr><td>0x0404</td><td><code>invalid_session_id</code></td><td>T</td><td>0</td><td>SessionID invalid for frame</td><td>Session-bound with 0, or Ping/Pong with &gt;0</td></tr><tr><td>0x0405</td><td><code>disallowed_sender</code></td><td>T</td><td>S</td><td>Wrong direction for frame</td><td>Client sends Signal, peer sends Control</td></tr></tbody></table><h3 id="internal-0x06xx" tabindex="-1">Internal (0x06xx) <a class="header-anchor" href="#internal-0x06xx" aria-label="Permalink to “Internal (0x06xx)”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Name</th><th>T/N</th><th>SID</th><th>Meaning</th><th>When Emitted</th></tr></thead><tbody><tr><td>0x0601</td><td><code>internal_error</code></td><td>T</td><td>0</td><td>Relay internal failure</td><td>Connection-fatal relay failure; reconnect may succeed on a healthy instance</td></tr></tbody></table><h3 id="throttling-0x09xx" tabindex="-1">Throttling (0x09xx) <a class="header-anchor" href="#throttling-0x09xx" aria-label="Permalink to “Throttling (0x09xx)”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Name</th><th>T/N</th><th>SID</th><th>Meaning</th><th>When Emitted</th></tr></thead><tbody><tr><td>0x0901</td><td><code>rate_limited</code></td><td>N</td><td>0</td><td>Too many requests</td><td>Message rate exceeded</td></tr><tr><td>0x0902</td><td><code>backpressure</code></td><td>T</td><td>0</td><td>Send buffer full</td><td>Receiver too slow</td></tr></tbody></table><p>Rate limiting (<code>rate_limited</code>) is non-terminal and connection-level — the connection stays open and the sender should back off. Backpressure (<code>backpressure</code>) is terminal — the slow consumer is closed because silently dropping forwarded frames would corrupt the E2EE sequence stream.</p><h3 id="session-state-0x10xx" tabindex="-1">Session State (0x10xx) <a class="header-anchor" href="#session-state-0x10xx" aria-label="Permalink to “Session State (0x10xx)”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Name</th><th>T/N</th><th>SID</th><th>Direction</th><th>Meaning</th></tr></thead><tbody><tr><td>0x1001</td><td><code>session_paused</code></td><td>N</td><td>S</td><td>Relay → Client</td><td>Daemon disconnected; traffic suspended</td></tr><tr><td>0x1002</td><td><code>session_resumed</code></td><td>N</td><td>S</td><td>Relay → Client</td><td>Daemon reconnected and ready</td></tr><tr><td>0x1003</td><td><code>session_ended</code></td><td>N</td><td>S</td><td>Relay → Daemon</td><td>Client disconnected; cleanup session</td></tr><tr><td>0x1004</td><td><code>session_pending</code></td><td>N</td><td>S</td><td>Relay → Client</td><td>Daemon reconnected; awaiting ready signal</td></tr></tbody></table><h2 id="endpoint-codes-sdk-only" tabindex="-1">Endpoint Codes (SDK Only) <a class="header-anchor" href="#endpoint-codes-sdk-only" aria-label="Permalink to “Endpoint Codes (SDK Only)”">​</a></h2><p>These codes exist for SDK error handling and logging. They are never transmitted in Control frames.</p><table tabindex="0"><thead><tr><th>Code</th><th>Name</th><th>Detected by</th><th>Meaning</th></tr></thead><tbody><tr><td>0xE001</td><td><code>identity_key_changed</code></td><td>Client</td><td>TOFU key mismatch; possible MITM</td></tr><tr><td>0xE002</td><td><code>handshake_failed</code></td><td>Client</td><td>Signature verification failed</td></tr><tr><td>0xE003</td><td><code>handshake_timeout</code></td><td>Either</td><td>30s handshake deadline exceeded</td></tr><tr><td>0xE004</td><td><code>decrypt_failed</code></td><td>Either</td><td>ChaCha20-Poly1305 decrypt/auth failed</td></tr><tr><td>0xE005</td><td><code>sequence_error</code></td><td>Either</td><td>Sequence outside replay window</td></tr></tbody></table><p><strong>Reserved ranges for endpoint codes:</strong></p><ul><li><code>0xE0xx</code>: SBRP v1 SDK codes</li><li><code>0xE1xx–0xEFxx</code>: Future SDK versions</li><li><code>0xF0xx–0xFFxx</code>: Vendor/application-specific</li></ul><h2 id="interpreting-t-n-and-sid" tabindex="-1">Interpreting T/N and SID <a class="header-anchor" href="#interpreting-t-n-and-sid" aria-label="Permalink to “Interpreting T/N and SID”">​</a></h2><p><strong>Terminality (T/N)</strong>:</p><ul><li><strong>T (Terminal)</strong>: Relay sends Control frame then closes WebSocket. Client should not retry on same connection.</li><li><strong>N (Non-terminal)</strong>: Connection remains open. Client may wait, retry, or take appropriate action.</li></ul><p><strong>SessionID scope (SID)</strong>:</p><ul><li><strong>0</strong>: Connection-level error; use SessionID=0 in frame header.</li><li><strong>S</strong>: Session-specific; use the relevant non-zero SessionID in frame header.</li></ul>',33)])])}const b=e(a,[["render",r]]);export{m as __pageData,b as default};
